import{_ as t,o,c as a,a0 as r}from"./chunks/framework.DmGDJU50.js";const p=JSON.parse('{"title":"Boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/boundaries.md","filePath":"explanation/boundaries.md"}'),i={name:"explanation/boundaries.md"};function d(s,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h1><h2 id="owns" tabindex="-1">Owns <a class="header-anchor" href="#owns" aria-label="Permalink to &quot;Owns&quot;">​</a></h2><p>The <strong>age identity&#39;s lifecycle</strong> — bootstrap (<code>init</code>), inspect (<code>show</code>/<code>backend</code>/<code>manifest</code>), and movement (<code>import</code>/<code>export</code>) of the single per-machine, per-human keyfile. Plus the keyfile <em>path</em> convention (<code>--identity-file</code> → <code>TARDIGRADA_IDENTITY_FILE</code> → XDG → <code>~/.config</code>) and the <code>identity.txt</code> on-disk format it writes.</p><h2 id="doesn-t-own" tabindex="-1">Doesn&#39;t own <a class="header-anchor" href="#doesn-t-own" aria-label="Permalink to &quot;Doesn&#39;t own&quot;">​</a></h2><ul><li><strong>Ciphertext</strong> — tardigrada never sees vaults, sealed packs, <code>rage</code> files, or any encrypted payload. It produces and moves the key; consumers do the sealing.</li><li><strong>Secret materialization</strong> — refs, env injection, audit: cuora.</li><li><strong>Distribution</strong> — the <code>tardigrada</code> command ships as a tamias <code>type: files</code> pack; tamias owns install/registry.</li><li><strong>Releases</strong> — tags and version bumps are tarsi&#39;s (<code>scripts/release.sh</code> is a shim); the work ledger is myco&#39;s (<code>project/</code>).</li></ul><h2 id="neighbors" tabindex="-1">Neighbors <a class="header-anchor" href="#neighbors" aria-label="Permalink to &quot;Neighbors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Neighbor</th><th>Relationship</th></tr></thead><tbody><tr><td><strong>cuora</strong></td><td>consumes age identities for vault decryption. Interop is file-level only: share the keyfile path (<code>CUORA_IDENTITY_FILE</code> ↔ <code>TARDIGRADA_IDENTITY_FILE</code>) or move material via <code>export --out</code>/<code>import</code>. No cuora-aware verbs here.</td></tr><tr><td><strong>tamias</strong></td><td>ships the binary — <code>libraries/tardigrada</code> pack, <code>type: files</code> payload bin staged by <code>scripts/pack.sh</code>.</td></tr><tr><td><strong>rage / age ecosystem</strong></td><td>the keyfile format is <code>identity.txt</code>-compatible — anything that reads <code>AGE-SECRET-KEY-…</code> files interoperates for free.</td></tr><tr><td><strong>cuora-identity-keyring</strong></td><td>upstream keyring impl exists but hardcodes the <code>&quot;cuora&quot;</code> service name — a tardigrada keyring backend waits on upstream parameterization (tracked in <code>project/</code>).</td></tr></tbody></table><h2 id="the-rule-of-thumb" tabindex="-1">The rule of thumb <a class="header-anchor" href="#the-rule-of-thumb" aria-label="Permalink to &quot;The rule of thumb&quot;">​</a></h2><p>If a feature needs to know what the identity <em>decrypts</em>, it belongs in the consumer (cuora, tamias sealed packs), not here. tardigrada stays a lifecycle tool: keys in, keys out, nothing in between.</p>',9)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
